const j = $json;

const stripHtml = (value = '') =>
  String(value)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();

const title = stripHtml(j.title || j.name || 'Без названия');
const link = String(j.link || j.guid || j.id || '').trim();
const content = stripHtml(
  j.contentSnippet ||
  j.content ||
  j.summary ||
  j.description ||
  j['content:encoded'] ||
  ''
);
const publishedAt =
  j.isoDate ||
  j.pubDate ||
  j.published ||
  j.updated ||
  new Date().toISOString();

let source = 'Неизвестный источник';
const host = (() => {
  try { return new URL(link).hostname.toLowerCase(); }
  catch { return ''; }
})();

if (host.includes('n8n.io')) source = 'n8n';
else if (host.includes('github.com')) source = 'n8n GitHub';
else if (host.includes('openai.com')) source = 'OpenAI';
else if (host.includes('googleblog.com')) source = 'Google Developers';

return {
  json: {
    title,
    link,
    content: content.slice(0, 6000),
    publishedAt,
    source
  }
};

const inputs = $input.all();
const output = [];
const now = Date.now();

const normalizeKey = (value = '') =>
  String(value)
    .toLowerCase()
    .replace(/^https?:\/\/(www\.)?/, '')
    .replace(/[?#].*$/, '')
    .replace(/[^a-zа-яё0-9]+/gi, ' ')
    .trim();

const weights = {
  n8n: 30,
  automation: 16,
  workflow: 14,
  'ai agent': 20,
  agentic: 16,
  mcp: 18,
  api: 10,
  webhook: 12,
  gemini: 14,
  openai: 12,
  anthropic: 12,
  claude: 10,
  llm: 10,
  rag: 12,
  'tool calling': 16,
  'function calling': 14,
  integration: 9,
  'telegram bot': 12,
  'breaking change': 24,
  deprecated: 24,
  deprecation: 24,
  migration: 18,
  security: 12,
  vulnerability: 18,
  release: 10,
  tutorial: 7,
};

const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};

const cutoff = now - 90 * 24 * 60 * 60 * 1000;

for (const [storedKey, timestamp] of Object.entries(staticData.seen)) {
  if (timestamp < cutoff) {
    delete staticData.seen[storedKey];
  }
}

for (const input of inputs) {
  const item = input.json ?? {};
  const text =
    `${item.title ?? ''} ${item.content ?? ''}`.toLowerCase();

  let score = 0;
  const matched = [];

  for (const [keyword, weight] of Object.entries(weights)) {
    if (text.includes(keyword)) {
      score += weight;
      matched.push(keyword);
    }
  }

  if (item.source === 'n8n GitHub') {
    score += 35;
  } else if (item.source === 'n8n') {
    score += 25;
  } else if (item.source === 'OpenAI') {
    score += 12;
  } else if (item.source === 'Google Developers') {
    score += 8;
  }

  const publishedMs = Date.parse(item.publishedAt);

  if (Number.isFinite(publishedMs)) {
    const ageHours = (now - publishedMs) / 3600000;

    if (ageHours <= 24) {
      score += 12;
    } else if (ageHours <= 72) {
      score += 6;
    } else if (ageHours > 24 * 21) {
      score -= 20;
    }
  }

  score = Math.max(0, Math.min(100, score));

  const key =
    normalizeKey(item.link) ||
    normalizeKey(item.title);

  if (!key) continue;
  if (staticData.seen[key]) continue;
  if (score < 38) continue;

  staticData.seen[key] = now;

  const preview = String(item.content ?? '').slice(0, 900);

  output.push({
    json: {
      ...item,
      score,
      matchedKeywords: matched,
      analysisInput: {
        title: item.title ?? 'Без названия',
        source: item.source ?? 'Неизвестный источник',
        publishedAt: item.publishedAt ?? '',
        content: preview,
        link: item.link ?? '',
        deterministicScore: score,
        matchedKeywords: matched,
      },
    },
  });
}

return output;

