const original = $('Оценка и дедупликация').item.json;
const aiText = String($json.text ?? $json.output ?? '').trim();

if (!aiText || /^SKIP[.!]?$/i.test(aiText)) return [];

const clean = aiText
  .replace(/^```(?:markdown|text)?\s*/i, '')
  .replace(/```$/i, '')
  .trim();

const maxBody = 3300;
const body = clean.length > maxBody
  ? `${clean.slice(0, maxBody)}…`
  : clean;

return {
  json: {
    ...original,
    telegramText: `${body}\n\n${original.link}`
  }
};
